import { ChatImage } from "./chat-image";
import { reactDeclaration } from "./util";

export type FileAttachmentPayload = {
    type: "file-attachment";
    contentType: string;
    url: string;
    name?: string;
};

export const FileAttachmentDeclaration = reactDeclaration<FileAttachmentPayload>({
    type: "file-attachment",
    name: "File Attachment",
    schema: `{
    type: "file-attachment";
    contentType: string;
    url: string;
    name?: string;
}`,
    renderPreview: data => {
        if (!data) {
            return null;
        }
        if (data.contentType.startsWith("image/")) {
            return <ChatImage src={data.url} maxHeight="200px" />;
        }
        return <FileDownload url={data.url} name={data.name} />;
    },
    render: data => {
        if (data.contentType.startsWith("image/")) {
            return <ChatImage src={data.url} maxHeight="200px" />;
        }
        return <FileDownload url={data.url} name={data.name} />;
    },
});

function FileDownload({ url, name }: { url: string; name?: string }) {
    return (
        <a
            href={url}
            target="_blank"
            rel="noopener noreferrer"
            download={name}
            style={{
                display: "inline-flex",
                alignItems: "center",
                gap: "8px",
                padding: "8px 12px",
                textDecoration: "underline",
                cursor: "pointer",
            }}
        >
            {name ?? "Download file"}
        </a>
    );
}
